//! Generates Rust constants from `design/tokens/*.css`.
//!
//! The CSS is the source of truth: edit it, never the generated file.
//! `:root` declarations become top-level constants (dark theme and palette).
//! `[data-theme="light"]` declarations become the `light` module.

#[path = "src/parse.rs"]
#[allow(dead_code)]
mod parse;

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::{env, fs};

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let dir = manifest.join("../../design/tokens");
    println!("cargo:rerun-if-changed={}", dir.display());

    let mut files: Vec<PathBuf> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|x| x == "css"))
        .collect();
    files.sort();

    let mut root = Vec::new();
    let mut light = Vec::new();
    let mut seen: BTreeMap<String, PathBuf> = BTreeMap::new();
    for file in &files {
        println!("cargo:rerun-if-changed={}", file.display());
        let css = fs::read_to_string(file).unwrap();
        for t in parse::declarations_in(&css, ":root") {
            if let Some(prev) = seen.insert(t.name.clone(), file.clone()) {
                panic!(
                    "token --{} declared in both {} and {}",
                    t.name,
                    prev.display(),
                    file.display()
                );
            }
            root.push(t);
        }
        light.extend(parse::declarations_in(&css, "[data-theme=\"light\"]"));
    }

    // Light overrides may reference root tokens, so resolve them together.
    let mut all = root.clone();
    all.extend(light.iter().map(|t| parse::Token {
        name: format!("light--{}", t.name),
        value: t.value.replace("var(--", "var(--light--"),
    }));
    // Light values fall back to root tokens that the light block does not redefine.
    let light_names: Vec<&str> = light.iter().map(|t| t.name.as_str()).collect();
    for t in &mut all {
        if t.name.starts_with("light--") {
            for r in &root {
                if !light_names.contains(&r.name.as_str()) {
                    t.value = t.value.replace(
                        &format!("var(--light--{})", r.name),
                        &format!("var(--{})", r.name),
                    );
                }
            }
        }
    }
    let resolved = parse::resolve(&all).unwrap_or_else(|e| panic!("token error: {e}"));

    let mut out =
        String::from("// @generated by build.rs from design/tokens/*.css. Do not edit.\n\n");
    let root_resolved: Vec<_> = resolved
        .iter()
        .filter(|t| !t.name.starts_with("light--"))
        .collect();
    for t in &root_resolved {
        emit(&mut out, &t.name, &t.value, "");
    }
    out.push_str("\n/// Light theme overrides. Tokens not listed here keep their dark value.\npub mod light {\n    use super::Color;\n");
    for t in resolved.iter().filter(|t| t.name.starts_with("light--")) {
        emit(
            &mut out,
            t.name.trim_start_matches("light--"),
            &t.value,
            "    ",
        );
    }
    out.push_str("}\n\n/// Every root token as `(css name, resolved value)`.\npub static ALL: &[(&str, &str)] = &[\n");
    for t in &root_resolved {
        writeln!(out, "    ({:?}, {:?}),", format!("--{}", t.name), t.value).unwrap();
    }
    out.push_str("];\n");

    let dest = Path::new(&env::var("OUT_DIR").unwrap()).join("tokens.rs");
    fs::write(dest, out).unwrap();
}

fn ident(name: &str) -> String {
    let id: String = name
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect();
    if id.starts_with(|c: char| c.is_ascii_digit()) {
        format!("_{id}")
    } else {
        id
    }
}

fn emit(out: &mut String, name: &str, value: &str, indent: &str) {
    let id = ident(name);
    if let Some(c) = parse::parse_color(value) {
        writeln!(
            out,
            "{indent}pub const {id}: Color = Color::new({}, {}, {}, {:?}f32);",
            c.r, c.g, c.b, c.a
        )
        .unwrap();
    } else if let Some(ms) = parse::parse_ms(value) {
        writeln!(
            out,
            "{indent}pub const {id}: std::time::Duration = std::time::Duration::from_millis({ms});"
        )
        .unwrap();
    } else if let Some(n) = parse::parse_number(value) {
        writeln!(out, "{indent}pub const {id}: f32 = {n:?}f32;").unwrap();
    } else {
        writeln!(out, "{indent}pub const {id}: &str = {value:?};").unwrap();
    }
}
